import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int from, to, capacity, flow;
        public Edge(int from, int to, int capacity, int flow) {
            this.from = from;
            this.to = to;
            this.capacity = capacity;
            this.flow = flow;
        }
    }

    static final int INF = 1 << 29;
    static int MAXN = 500;
    static int n, t, xb, yb;
    static boolean[][] m = new boolean[11][11];
    static int[][] temp = new int[11][11], kaps = new int[11][11];
    static List<Integer>[] g = new ArrayList[MAXN];
    static List<Edge> e = new ArrayList<>();
    static int[] d = new int[MAXN], ptr = new int[MAXN];

    static {
        for (int i = 0; i < MAXN; i++) {
            g[i] = new ArrayList<>();
        }
    }

    static int way(int x1, int y1, int x2, int y2) {
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, x1, y1});
        int[][] h = new int[n][n];
        for (int[] row : h) Arrays.fill(row, INF);
        while (!q.isEmpty()) {
            int[] v = q.poll();
            int vdist = v[0], x = v[1], y = v[2];
            h[x][y] = vdist;
            if (x > 0 && m[x - 1][y] && h[x - 1][y] > h[x][y] + 1 && ((x - 1 == x2 && y == y2 && temp[x - 1][y] >= h[x][y] + 1) || !(x - 1 == x2 && y == y2) && temp[x - 1][y] > h[x][y] + 1))
                q.offer(new int[]{vdist + 1, x - 1, y});
            if (y > 0 && m[x][y - 1] && h[x][y - 1] > h[x][y] + 1 && ((x == x2 && y - 1 == y2 && temp[x][y - 1] >= h[x][y] + 1) || !(x == x2 && y - 1 == y2) && temp[x][y - 1] > h[x][y] + 1))
                q.offer(new int[]{vdist + 1, x, y - 1});
            if (x < n - 1 && m[x + 1][y] && h[x + 1][y] > h[x][y] + 1 && ((x + 1 == x2 && y == y2 && temp[x + 1][y] >= h[x][y] + 1) || !(x + 1 == x2 && y == y2) && temp[x + 1][y] > h[x][y] + 1))
                q.offer(new int[]{vdist + 1, x + 1, y});
            if (y < n - 1 && m[x][y + 1] && h[x][y + 1] > h[x][y] + 1 && ((x == x2 && y + 1 == y2 && temp[x][y + 1] >= h[x][y] + 1) || !(x == x2 && y + 1 == y2) && temp[x][y + 1] > h[x][y] + 1))
                q.offer(new int[]{vdist + 1, x, y + 1});
        }
        return h[x2][y2];
    }

    static void add_edge(int a, int b, int cap) {
        e.add(new Edge(a, b, cap, 0));
        g[a].add(e.size() - 1);
        e.add(new Edge(b, a, 0, 0));
        g[b].add(e.size() - 1);
    }

    static boolean bfs() {
        Arrays.fill(d, -1);
        Queue<Integer> q = new LinkedList<>();
        q.offer(0);
        d[0] = 0;
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int id : g[v]) {
                int to = e.get(id).to;
                if (d[to] == -1 && e.get(id).flow < e.get(id).capacity) {
                    d[to] = d[v] + 1;
                    q.offer(to);
                }
            }
        }
        return d[n * n * 2 + 1] != -1;
    }

    static int dfs(int v, int flow) {
        if (flow == 0) return 0;
        if (v == n * n * 2 + 1) return flow;
        for (; ptr[v] < g[v].size(); ptr[v]++) {
            int id = g[v].get(ptr[v]);
            int to = e.get(id).to;
            if (d[to] != d[v] + 1) continue;
            int pushed = dfs(to, Math.min(flow, e.get(id).capacity - e.get(id).flow));
            if (pushed > 0) {
                e.get(id).flow += pushed;
                e.get(id ^ 1).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int max_flow() {
        int flow = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = dfs(0, INF)) > 0) {
                flow += pushed;
            }
        }
        return flow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXN; i++) {
            g[i].clear();
        }
        e.clear();

        int k = 1;
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                temp[i][j] = t;
                if (c == 'Z') {
                    xb = i;
                    yb = j;
                    m[i][j] = false;
                } else if (c == 'Y') {
                    m[i][j] = false;
                } else {
                    m[i][j] = true;
                }
                add_edge(0, k++, (c == 'Z' || c == 'Y') ? 0 : c - '0');
            }
        }

        int base = n * n + 1;
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                if (c >= '0' && c <= '9') kaps[i][j] = c - '0';
                add_edge(base + (i * n + j), n * n * 2 + 1, (c == 'Z' || c == 'Y') ? 0 : c - '0');
            }
        }

        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, xb, yb});
        while (!q.isEmpty()) {
            int[] v = q.poll();
            int vdist = v[0], x = v[1], y = v[2];
            temp[x][y] = vdist;
            if (x > 0 && vdist + 1 < temp[x - 1][y] && m[x - 1][y]) q.offer(new int[]{vdist + 1, x - 1, y});
            if (y > 0 && vdist + 1 < temp[x][y - 1] && m[x][y - 1]) q.offer(new int[]{vdist + 1, x, y - 1});
            if (x < n - 1 && vdist + 1 < temp[x + 1][y] && m[x + 1][y]) q.offer(new int[]{vdist + 1, x + 1, y});
            if (y < n - 1 && vdist + 1 < temp[x][y + 1] && m[x][y + 1]) q.offer(new int[]{vdist + 1, x, y + 1});
        }

        int total_nodes = n * n;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int k1 = total_nodes * (i * n + j);
                for (int z = 0; z < n; z++) {
                    for (int w = 0; w < n; w++) {
                        if (m[i][j] && m[z][w] && way(i, j, z, w) <= t)
                            add_edge(base + i * n + j, (z * n + w) + total_nodes, INF);
                    }
                }
            }
        }

        System.out.println(max_flow());
    }
}
